-- Krpex Code v2, Phase 2 (plan.md "Krpex Code v2"): problems 71–150. Mirrors lib/code/problems-more.ts and the
-- tags in lib/code/meta.ts; tests/db/coding.test.ts checks they agree. Run after 029. Safe to run twice.

on conflict (slug) do update set
  title = excluded.title, topic = excluded.topic, difficulty = excluded.difficulty,
  tests = excluded.tests, position = excluded.position, tags = excluded.tags, active = true;
